import { bookPage, homePage, messagePage } from './views.js';

const MAX_BODY_BYTES = 64 * 1024;
const LIMITS = { title: 300, author: 300, notes: 10000 };

class HttpError extends Error {
  constructor(status, title, message) {
    super(message);
    this.status = status;
    this.title = title;
  }
}

export function createApp(store) {
  return createServer(async (req, res) => {
    try {
      await route(store, req, res);
    } catch (err) {
      if (err instanceof HttpError) {
        sendHtml(res, err.status, messagePage(err.title, err.message));
      } else {
        console.error(err);
        sendHtml(res, 500, messagePage('Something went wrong', 'The change could not be saved. Please try again.'));
      }
    }
  });
}

async function route(store, req, res) {
  const { pathname } = new URL(req.url, 'http://localhost');
  const bookMatch = pathname.match(/^\/books\/([^/]+)$/);
  const finishMatch = pathname.match(/^\/books\/([^/]+)\/finish$/);

  if (pathname === '/') {
    allow(req, 'GET');
    return sendHtml(res, 200, homePage(store.list()));
  }

  if (pathname === '/books') {
    allow(req, 'POST');
    const form = await readForm(req);
    const values = {
      title: (form.get('title') ?? '').trim(),
      author: (form.get('author') ?? '').trim(),
      notes: (form.get('notes') ?? '').trim(),
    };
    const error = validate(values);
    if (error) return sendHtml(res, 400, homePage(store.list(), { error, values }));
    const book = await store.add(values);
    return redirect(res, `/books/${book.id}`);
  }

  if (bookMatch) {
    allow(req, 'GET');
    const book = store.get(decodeURIComponent(bookMatch[1]));
    if (!book) throw notFound();
    return sendHtml(res, 200, bookPage(book));
  }

  if (finishMatch) {
    allow(req, 'POST');
    const book = await store.finish(decodeURIComponent(finishMatch[1]));
    if (!book) throw notFound();
    // Go back to the page the button was on (home or the book page).
    const back = sameOriginPath(req.headers.referer, req.headers.host);
    return redirect(res, back ?? '/');
  }

  throw new HttpError(404, 'Not found', 'There is no page here.');
}

function validate({ title, author, notes }) {
  if (!title) return 'Please enter a title.';
  if (!author) return 'Please enter an author.';
  if (title.length > LIMITS.title) return `Title must be at most ${LIMITS.title} characters.`;
  if (author.length > LIMITS.author) return `Author must be at most ${LIMITS.author} characters.`;
  if (notes.length > LIMITS.notes) return `Notes must be at most ${LIMITS.notes} characters.`;
  return '';
}

function notFound() {
  return new HttpError(404, 'Book not found', 'That book does not exist. It may have been removed, or the link is wrong.');
}

function allow(req, method) {
  if (req.method !== method && !(method === 'GET' && req.method === 'HEAD')) {
    throw new HttpError(405, 'Method not allowed', `Use ${method} for this page.`);
  }
}

async function readForm(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new HttpError(413, 'Too much text', 'That form was too large to save.');
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function sameOriginPath(referer, host) {
  if (!referer || !host) return null;
  try {
    const url = new URL(referer);
    return url.host === host ? url.pathname : null;
  } catch {
    return null;
  }
}

function sendHtml(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'",
    'X-Content-Type-Options': 'nosniff',
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}
"}

